<template>
  <main class="eng-page"><span class="eng-eyebrow">SOFEP / KẾT NỐI VÀ TRI ÂN</span><h1>Thông báo &amp; chiến dịch</h1><p class="eng-muted">Gửi vào trung tâm thông báo Customer. Không gửi marketing qua email hoặc SMS.</p>
    <div v-if="error" class="eng-error" role="alert">{{ error }}</div><div v-if="message" class="eng-success" role="status">{{ message }}</div>
    <div class="eng-grid"><section class="eng-panel"><h2>Soạn thông báo</h2><form @submit.prevent="preview">
      <label for="campaign-title">Tiêu đề</label><input id="campaign-title" v-model="form.title" maxlength="160" required>
      <label for="campaign-body">Nội dung</label><textarea id="campaign-body" v-model="form.body" maxlength="5000" required rows="5"></textarea>
      <label for="campaign-kind">Loại thông báo</label><select id="campaign-kind" v-model="form.kind"><option value="general">Thông báo chung</option><option value="promotion">Khuyến mãi</option><option value="thanks">Tri ân</option><option value="voucher">Voucher</option></select>
      <label for="campaign-voucher">Voucher liên kết · tùy chọn</label><select id="campaign-voucher" v-model="form.voucher_id" :disabled="form.kind==='general'"><option :value="null">Không liên kết voucher</option><option v-for="v in vouchers" :key="v.id" :value="v.id">{{ v.ma_code }} · {{ v.ten_giam_gia }}</option></select>
      <p v-if="form.voucher_id" class="eng-muted">Khi xác nhận, mã được phát riêng cho tập Customer này. Mã đã có lịch sử sử dụng công khai không được chuyển thành mã riêng. Lưu mã không trừ lượt.</p>
      <label for="campaign-send-at">Thời điểm gửi · Asia/Ho_Chi_Minh</label><input id="campaign-send-at" type="datetime-local" v-model="form.send_at"><p class="eng-muted">Để trống để xếp hàng gửi ngay. Lịch tương lai được worker giao khi đến hạn.</p>
      <div class="eng-actions"><button class="eng-btn" :disabled="busy || !ready">{{ busy?'Đang kiểm tra…':'Xem trước người nhận' }}</button></div>
    </form><details v-if="ready" class="eng-divider"><summary>Tạo voucher mới</summary><CampaignVoucherForm @created="voucherCreated" /></details></section>
    <section class="eng-panel"><h2>Đối tượng nhận</h2><p class="eng-muted">Không đặt ngưỡng: tất cả Customer hoạt động. Điều kiện đơn hàng và chi tiêu được kết hợp AND. Khuyến mãi/voucher loại trừ người đã tắt nhận tin.</p>
      <label for="campaign-period">Kỳ tính · theo ngày tạo đơn đã hoàn tất</label><select id="campaign-period" v-model="form.period"><option value="all">Tất cả thời gian</option><option value="week">Tuần hiện tại · thứ Hai đến Chủ nhật</option><option value="month">Tháng hiện tại</option><option value="year">Năm hiện tại</option></select>
      <div class="eng-grid"><div><label for="campaign-orders-min">Số đơn hoàn tất ≥</label><input id="campaign-orders-min" type="number" min="0" v-model="form.ordersMin"></div><div><label for="campaign-orders-max">Số đơn hoàn tất ≤</label><input id="campaign-orders-max" type="number" min="0" v-model="form.ordersMax"></div><div><label for="campaign-spend-min">Tổng thực chi ≥ (đ)</label><input id="campaign-spend-min" type="number" min="0" v-model="form.spendMin"></div><div><label for="campaign-spend-max">Tổng thực chi ≤ (đ)</label><input id="campaign-spend-max" type="number" min="0" v-model="form.spendMax"></div></div>
      <p class="eng-muted">Chỉ tính đơn đã giao + đã thanh toán, loại đơn hủy/hoàn tiền. Ranh giới kỳ theo giờ Việt Nam; số liệu lấy từ backend.</p><label class="eng-check"><input type="checkbox" v-model="form.recheck"> Voucher yêu cầu còn đạt điều kiện tại thời điểm lưu/checkout</label>
      <div v-if="previewData" class="eng-divider"><span class="eng-tag">Xem trước</span><h2 style="margin-top:12px">{{ previewData.count }} Customer đủ điều kiện</h2><h3>{{ form.title }}</h3><p style="white-space:pre-wrap;overflow-wrap:anywhere">{{ form.body }}</p><p class="eng-muted">{{ form.send_at ? form.send_at.replace('T',' ')+' (giờ Việt Nam)' : 'Xếp hàng gửi ngay' }}</p><template v-if="selectedVoucher"><p><strong>{{ selectedVoucher.ma_code }}</strong> · {{ selectedVoucher.loai_giam==='phan_tram'?selectedVoucher.gia_tri+'%':money(selectedVoucher.gia_tri) }}<br><span class="eng-muted">Tối thiểu {{ money(selectedVoucher.gia_tri_toi_thieu) }} · Giảm tối đa {{ selectedVoucher.giam_toi_da?money(selectedVoucher.giam_toi_da):'theo giá trị mã' }}<br>Hết hạn {{ selectedVoucher.ngay_ket_thuc || 'không giới hạn' }} · {{ selectedVoucher.gioi_han_moi_khach || 'theo cấu hình' }} lượt/khách</span></p></template><button v-if="!confirmSend" class="eng-btn" :disabled="busy || !previewData.count" @click="confirmSend=true">Tiếp tục xác nhận</button><div v-else class="eng-panel"><h3>Xác nhận gửi thông báo?</h3><p class="eng-muted">{{ previewData.count }} Customer sẽ được đưa vào hàng đợi. Backend kiểm tra lại tập người nhận trước khi lưu. Có thể bị bỏ qua nếu tài khoản bị khóa hoặc tắt nhận tin trước lúc giao.</p><div class="eng-actions"><button class="eng-btn" :disabled="busy || !ready" @click="send">Xác nhận xếp hàng gửi</button><button class="eng-btn secondary" :disabled="busy || !ready" @click="confirmSend=false">Quay lại</button></div></div></div>
    </section></div>
    <section class="eng-panel"><h2>Lịch sử chiến dịch</h2><div class="eng-actions"><button class="eng-btn secondary" :disabled="busy" @click="load">Làm mới</button><button class="eng-btn secondary" :disabled="busy || !ready" @click="dispatch">Giao một lô đến hạn · tối đa 100 người</button></div><p class="eng-muted">Hàng đợi bền vững; scheduler giao mỗi phút khi được vận hành. Retry không tạo thông báo trùng; lỗi thử lại tối đa 3 lần.</p><div class="eng-table-wrap"><table><thead><tr><th>Chiến dịch</th><th>Lịch gửi (VN)</th><th>Tập nhận</th><th>Thành công</th><th>Chờ</th><th>Lỗi</th><th>Bỏ qua</th></tr></thead><tbody><tr v-for="c in campaigns" :key="c.id"><td><strong>{{ c.title }}</strong><br>{{ c.status==='queued'?'Đang chờ giao':'Đã xử lý các lượt gửi' }}</td><td>{{ date(c.send_at) }}</td><td>{{ c.recipient_count }}</td><td>{{ c.delivered||0 }}</td><td>{{ c.pending||0 }}</td><td>{{ c.failed||0 }}</td><td>{{ c.skipped||0 }}</td></tr></tbody></table></div><p v-if="!campaigns.length" class="eng-muted">Chưa có chiến dịch.</p><div v-if="lastPage>1" class="eng-actions"><button class="eng-btn secondary" :disabled="page<=1" @click="page--;load()">Trước</button><span>{{ page }}/{{ lastPage }}</span><button class="eng-btn secondary" :disabled="page>=lastPage" @click="page++;load()">Sau</button></div></section>
  </main>
</template>
<script>
import CampaignVoucherForm from './CampaignVoucherForm.vue';
import { engagementApi, engagementError, engagementDate, money } from '../../services/engagement';
export default {
  components:{CampaignVoucherForm},data:()=>({form:{title:'',body:'',kind:'general',voucher_id:null,send_at:'',period:'all',ordersMin:'',ordersMax:'',spendMin:'',spendMax:'',recheck:false},previewData:null,confirmSend:false,sendKey:'',ready:false,busy:false,error:'',message:'',vouchers:[],campaigns:[],page:1,lastPage:1}),
  computed:{selectedVoucher(){return this.vouchers.find(v=>v.id===this.form.voucher_id);},payload(){const f=this.form,filters={period:f.period};for(const [key,min,max] of [['orders',f.ordersMin,f.ordersMax],['spend',f.spendMin,f.spendMax]]){const range={};if(min!=='')range.min=Number(min);if(max!=='')range.max=Number(max);if(Object.keys(range).length)filters[key]=range;}return {title:f.title,body:f.body,kind:f.kind,voucher_id:f.voucher_id,send_at:f.send_at||null,recheck:f.recheck,filters};}},
  watch:{form:{deep:true,handler(){this.previewData=null;this.confirmSend=false;this.sendKey='';if(this.form.kind==='general')this.form.voucher_id=null;}}},mounted(){this.load();},
  methods:{money,date:engagementDate,
    async load(){this.error='';try{const [campaigns,vouchers]=await Promise.all([engagementApi('admin/chien-dich?page='+this.page),engagementApi('admin/ma-giam-gia/get-data')]);this.campaigns=campaigns.data.data.data;this.lastPage=campaigns.data.data.last_page;this.vouchers=vouchers.data.data;this.ready=true;}catch(e){this.ready=false;this.error=engagementError(e);}},
    async voucherCreated(code){await this.load();const v=this.vouchers.find(v=>v.ma_code===code);this.form.kind='voucher';this.$nextTick(()=>{this.form.voucher_id=v?.id||null;});this.message='Đã tạo voucher; xem trước đối tượng trước khi gửi.';},
    async preview(){if(this.busy)return;this.busy=true;this.error='';this.confirmSend=false;try{const payload=this.payload;const version=JSON.stringify(payload);const {data}=await engagementApi('admin/chien-dich/xem-truoc',{method:'post',data:payload});if(version!==JSON.stringify(this.payload))return;this.previewData=data.data;this.sendKey=crypto.randomUUID();}catch(e){this.error=engagementError(e);}finally{this.busy=false;}},
    async send(){if(this.busy||!this.confirmSend||!this.previewData)return;this.busy=true;this.error='';try{await engagementApi('admin/chien-dich',{method:'post',data:{...this.payload,preview_hash:this.previewData.preview_hash,request_key:this.sendKey}});this.message='Đã đóng băng tập người nhận và xếp hàng. Worker sẽ giao khi đến hạn.';this.confirmSend=false;this.previewData=null;await this.load();}catch(e){this.error=engagementError(e);}finally{this.busy=false;}},
    async dispatch(){if(this.busy)return;this.busy=true;this.error='';try{const {data}=await engagementApi('admin/chien-dich/giao-lo',{method:'post'});this.message='Đã giao '+data.delivered+' thông báo trong lô này.';await this.load();}catch(e){this.error=engagementError(e);}finally{this.busy=false;}}
  }
};
</script>
<style src="../../assets/css/engagement.css"></style>
